import math

def binomial_p_value(k, n, alternative):
    """Exact p-value for k wins in n fair trades.
    alternative: 'greater', 'less' or 'two-sided'."""
    total = 2 ** n
    upper = sum(math.comb(n, j) for j in range(k, n + 1)) / total
    lower = sum(math.comb(n, j) for j in range(0, k + 1)) / total
    if alternative == 'greater':
        return upper
    if alternative == 'less':
        return lower
    return min(1.0, 2 * min(upper, lower))
